(()=>{const out={},ns='http://www.w3.org/2000/svg',s=document.createElementNS(ns,'svg'),defs=document.createElementNS(ns,'defs');s.setAttribute('width','200');s.setAttribute('height','100');s.append(defs);document.body.append(s);const rect=document.createElementNS(ns,'rect');rect.id='r';rect.setAttribute('x','10');rect.setAttribute('y','20');rect.setAttribute('width','30');rect.setAttribute('height','40');defs.append(rect);const u=document.createElementNS(ns,'use');u.setAttribute('href','#r');u.setAttribute('x','5');u.setAttribute('y','7');s.append(u);const box=n=>{const b=n.getBBox();return [b.x,b.y,b.width,b.height]};out.basic=box(u);rect.setAttribute('transform','scale(2)');out.targetTransform=box(u);u.setAttribute('transform','translate(100 200)');out.ownTransform=box(u);out.parent=box(s);rect.setAttribute('width','50');out.mutation=box(u);u.setAttribute('href','#absent');out.missing=box(u);u.setAttribute('href','#r');rect.style.display='none';out.hidden=box(u);rect.style.display='';const symbol=document.createElementNS(ns,'symbol');symbol.id='symbol';symbol.setAttribute('viewBox','0 0 100 50');const q=document.createElementNS(ns,'rect');q.setAttribute('width','100');q.setAttribute('height','50');symbol.append(q);defs.append(symbol);u.setAttribute('href','#symbol');u.setAttribute('width','40');u.setAttribute('height','30');out.symbol=box(u);u.id='cycle';u.setAttribute('href','#cycle');out.cycle=box(u);s.remove();return out})()